   await p.locator('#quoteImportSupplier').selectOption('U24-A');await p.locator('#quoteRoundSelect').selectOption('2|1');await p.locator('#confirmQuoteRound').scrollIntoViewIfNeeded();await check('C09 '+width+' lock and visible explanation',await p.locator('#confirmQuoteRound').isDisabled()&&await p.locator('#srmV3QuoteLockHint').isVisible(),true);await shot('C09-'+width+'-quote-lock');await heading.scrollIntoViewIfNeeded();
  }
  const layout=await p.evaluate(()=>({viewport:{width:innerWidth,height:innerHeight},documentWidth:document.documentElement.scrollWidth,sidebar:document.querySelector('.srm-v2-sidebar').getBoundingClientRect().toJSON(),active:document.querySelector('.srm-v2-sideitem[aria-current="page"]')?.getAttribute('data-srm-v2-tab'),bodyBackground:getComputedStyle(document.body).backgroundColor,tables:[...document.querySelector('section.panel.active').querySelectorAll('.tablewrap')].filter(e=>e.getBoundingClientRect().width>0).map(e=>({width:e.clientWidth,scrollWidth:e.scrollWidth,overflowX:getComputedStyle(e).overflowX,tableWidth:e.querySelector('table')?.getBoundingClientRect().width})),focus:{tag:document.activeElement.tagName,id:document.activeElement.id}}));
