   await p.locator('#itemSearch').fill('UAT28-HIGH');await p.locator('#itemSearch').press('Enter');await check('C09 '+width+' keyboard material search row count',await p.locator('#itemBody tr').count(),1);await check('C09 '+width+' filtered correct item',(await p.locator('#itemBody').innerText()).includes('UAT28-HIGH'),true);await shot('C09-'+width+'-items-search');await p.locator('#clearItemSearch').click();await check('C09 '+width+' clear search restores all4 rows',await p.locator('#itemBody tr').count(),4);
