 await p.locator('[data-srm-v2-tab="quotes"]').focus();await p.keyboard.press('Enter');await check('C09 '+width+' keyboard sidebar Enter navigates',await p.locator('section.panel.active').getAttribute('id'),'quotes');await tell('C09 '+width+' keyboard focus',await p.evaluate(()=>({tag:document.activeElement.tagName,id:document.activeElement.id,outline:getComputedStyle(document.activeElement).outline})));
}
